import React, { useState } from "react";
import StudentForm from "./components/StudentForm";
import StudentList from "./components/StudentList";
import StudentDetails from "./components/StudentDetails";
import "./styles.css";
          import { FaDownload, FaEye, FaEdit, FaTrash } from "react-icons/fa";

import {
  getStudents,
  addStudent as addStudentService,
  updateStudent as updateStudentService,
  deleteStudent as deleteStudentService,
} from "./services/studentService";

export default function App() {
  const [students, setStudents] = useState([]);
  const [selected, setSelected] = useState(null);
  const [editStudent, setEditStudent] = useState(null);

  const loadStudents = async () => {
    const data = await getStudents();
    setStudents(data);
  };

  const addStudent = async (s) => {
    const newStudent = await addStudentService({ ...s, id: Date.now() });
    setStudents([...students, newStudent]);
  };

  const updateStudent = async (s) => {
    const updated = await updateStudentService(s.id, s);
    setStudents(students.map(st => (st.id === s.id ? updated : st)));
    setEditStudent(null);
  };

  const deleteStudent = async (id) => {
    await deleteStudentService(id);
    setStudents(students.filter(st => st.id !== id));
    if (selected?.id === id) setSelected(null);
  };

  return (
    <div className="app-container">
      <h1 className="title">Student Result Dashboard</h1>

      <div className="layout">
        <div className="left-panel">

      <button className="btn load-btn">
         <FaDownload className="icon-sm" />
              Load Students
        </button>

          <StudentForm 
            onAdd={addStudent} 
            onUpdate={updateStudent} 
            studentToEdit={editStudent}
          />
          <StudentList 
            students={students} 
            onSelect={setSelected} 
            onDelete={deleteStudent} 
            onEdit={setEditStudent} 
          />
        </div>

        <div className="right-panel">
          {selected ? <StudentDetails student={selected} /> : <p>Select a student to view details.</p>}
        </div>
      </div>
    </div>
  );
}
